insert into academy_sections (slug, title, blurb, guide_refs) values ('new-r35-fleet-payments', 'Taking payments on the Money tab', 'Fleet collects payments on a booking: a pay link, the saved card, the deposit hold, or cash and e-Transfer within your limit. Refunds stay with Finance.', array['va/fleet']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-fleet-payments'), 1, 'What you can collect', '[{"caption":"The Money tab","say":"Open a booking and press its Money tab. Fleet can take the payment that is due without waiting for the office.","visual":{"kind":"title","heading":"Money tab","text":"Collect what is due"}},{"caption":"Four ways","say":"Text or email a pay link, charge the saved card when the renter agreed to it, hold the deposit on the card, or record cash or an e-Transfer you received.","visual":{"kind":"list","heading":"Ways to collect","items":["A pay link by text or email","The saved card, when the renter agreed","The deposit hold on the card","Cash or an e-Transfer you received"]}},{"caption":"Not for Fleet","say":"Refunds, captures and voids are not on your Money tab. They stay with Finance and the Admins.","visual":{"kind":"rule","heading":"No refunds","text":"A renter asks for money back: tell them Finance or an Admin handles it.","tone":"warn"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-fleet-payments'), 2, 'Cash and e-Transfer within your limit', '[{"caption":"Record what you received","say":"Cash or an e-Transfer you received is recorded on the booking with the amount and how it came. It counts toward the booking at once.","visual":{"kind":"steps","heading":"Record it","items":["Open the Money tab","Choose the way: cash or e-Transfer","Enter the amount and save"]}},{"caption":"Your single limit","say":"One payment you record cannot be above your single limit. Above it, ask an Admin or Finance to record it.","visual":{"kind":"rule","heading":"The limit","text":"A payment above your limit is not recorded by Fleet.","tone":"warn"}},{"caption":"Finance checks it","say":"Each payment you record gives Finance a To do to check it. Record only what you really received.","visual":{"kind":"chat","lines":[{"who":"you","text":"Recorded $200 cash for CC-10483."},{"who":"app","text":"Finance has a To do: check the payment Fleet recorded."}]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-fleet-payments'), 1, 'Where does Fleet collect a payment?', '["Only in the Admin portal","On the booking''s Money tab","By email to Finance","Fleet cannot collect"]'::jsonb, 1, 'Fleet has the Money tab on a booking.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-fleet-payments'), 2, 'Which of these can Fleet do?', '["Refund a deposit","Void a payment","Hold the deposit on the card","Capture a hold"]'::jsonb, 2, 'Fleet collects and holds; refunds, captures and voids stay with Finance and the Admins.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-fleet-payments'), 3, 'The renter hands you cash above your single limit. What do you do?', '["Record it anyway","Ask an Admin or Finance to record it","Keep it unrecorded","Split it in two payments"]'::jsonb, 1, 'A payment above your limit is for an Admin or Finance.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-fleet-payments'), 4, 'What happens after you record cash or an e-Transfer?', '["Nothing","Finance gets a To do to check it","The renter is refunded","The booking is cancelled"]'::jsonb, 1, 'Every payment Fleet records is checked by Finance.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-fleet-payments'), 5, 'When may you charge the saved card?', '["Whenever it is useful","When the renter agreed to it","Never","Only after the return"]'::jsonb, 1, 'The saved card is charged only when the renter agreed.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_path_sections (path_code, section_id, sort) select 'fleet', (select id from academy_sections where slug = 'new-r35-fleet-payments'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'fleet' on conflict (path_code, section_id) do nothing;
insert into academy_sections (slug, title, blurb, guide_refs) values ('new-r35-fleet-phone', 'Calls and texts on the Fleet lane', 'Calls and texts about pickups, returns, deliveries and cars on rent come to Fleet first: the caller pop-up, the Calls and texts page and Returning now.', array['va/fleet', 'va/texts-and-calls']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-fleet-phone'), 1, 'Your own lane', '[{"caption":"Fleet first","say":"A call or text about a car on rent, or a pickup, return, delivery or collection within a day, is on the Fleet lane. Anything else goes to customer service.","visual":{"kind":"list","heading":"On the Fleet lane","items":["A car on rent","A pickup or return within a day","A delivery or collection within a day"]}},{"caption":"The caller pop-up","say":"When a renter calls, the pop-up shows who it is and their booking. Answer from it. If nobody on Fleet is on duty, or nobody answers in 20 seconds, customer service sees it too.","visual":{"kind":"rule","heading":"Answer from the pop-up","text":"A call on your lane shows to Fleet first.","tone":"ok"}},{"caption":"Calls and texts page","say":"More fleet, then Calls and texts, is your inbox. It has a Fleet tab and a Customer service tab, and each conversation says its lane.","visual":{"kind":"steps","heading":"Find it","items":["Open More fleet","Press Calls and texts","Open a conversation to answer it"]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-fleet-phone'), 2, 'A car that is late', '[{"caption":"Returning now","say":"A car late back has Returning now on its late panel. Press it when the renter says they are on the way.","visual":{"kind":"title","heading":"Returning now","text":"On the late panel"}},{"caption":"What it does","say":"The renter gets no more overdue reminders for that return time. If the renter is not really coming, do not press it.","visual":{"kind":"rule","heading":"Honest button","text":"Press it only when the renter said they are on the way.","tone":"warn"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-fleet-phone'), 1, 'A renter calls about the car they have on rent. Whose lane is it?', '["Customer service only","Fleet first","Sales","Nobody"]'::jsonb, 1, 'A car on rent is on the Fleet lane.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-fleet-phone'), 2, 'Nobody on Fleet answers a call for 20 seconds. What happens?', '["The call is lost","Customer service sees it too","The renter is blocked","It is deleted"]'::jsonb, 1, 'Customer service sees a Fleet call that is not answered in time.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-fleet-phone'), 3, 'Where is the Fleet inbox for calls and texts?', '["More fleet, then Calls and texts","The owner portal","Money tab","Training"]'::jsonb, 0, 'It is the Calls and texts page under More fleet.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-fleet-phone'), 4, 'When do you press Returning now?', '["Always","When the renter says they are on the way back","When the car is on time","After the return"]'::jsonb, 1, 'It stops the overdue reminders, so only press it when the renter is on the way.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-fleet-phone'), 5, 'What does Returning now stop?', '["The booking","The renter''s overdue reminders for that return time","The deposit","The tracker"]'::jsonb, 1, 'The renter gets no more overdue reminders for that return time.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_path_sections (path_code, section_id, sort) select 'fleet', (select id from academy_sections where slug = 'new-r35-fleet-phone'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'fleet' on conflict (path_code, section_id) do nothing;
